class ContentDetailPage extends StatefulWidget{final EditorialApi api;final String itemId;const ContentDetailPage({super.key,required this.api,required this.itemId});@override State<ContentDetailPage> createState()=>_ContentDetailPageState();}
class _ContentDetailPageState extends State<ContentDetailPage>{late Future<List<dynamic>> future;String role='';
 @override void initState(){super.initState();future=_load();}
 Future<List<dynamic>> _load()async{final values=await Future.wait([widget.api.itemDetail(widget.itemId),widget.api.me()]);role=(values[1] as Map<String,dynamic>)['role']?.toString()??'';return values;}
 void _reload()=>setState(()=>future=_load());
 bool get canEdit=>role=='owner'||role=='editor';bool get canReview=>role=='owner'||role=='reviewer';bool get canPublish=>role=='owner'||role=='publisher';bool get isOwner=>role=='owner';
 @override Widget build(BuildContext context)=>FutureBuilder<List<dynamic>>(future:future,builder:(context,s){if(s.connectionState!=ConnectionState.done)return const Scaffold(body:Center(child:CircularProgressIndicator()));if(s.hasError)return Scaffold(appBar:AppBar(),body:StudioErrorState(onRetry:_reload,message:s.error.toString()));final data=s.data![0] as Map<String,dynamic>;final item=data['item'] as Map<String,dynamic>;return DefaultTabController(length:6,child:Scaffold(appBar:AppBar(title:Text(item['title']??'Contenu'),actions:[IconButton(tooltip:'Actualiser',onPressed:_reload,icon:const Icon(Icons.refresh))]),body:Column(children:[_Header(item:item,role:role,onEdit:canEdit&&['draft','changes_requested'].contains(item['state'])?()=>_editMetadata(item):null),_ActionBar(item:item,onRevision:canEdit?()=>_addRevision(data):null,onSubmit:canEdit&&['draft','changes_requested'].contains(item['state'])?()=>_submit(item):null,onReview:canReview&&item['state']=='in_review'?()=>_review(item):null,onPublish:canPublish&&item['state']=='approved'?()=>_publish(item):null,onArchive:canPublish&&item['state']=='published'?()=>_archive(item):null,onAssign:isOwner?()=>_assign(item):null),const TabBar(isScrollable:true,tabs:[Tab(text:'Vue d’ensemble'),Tab(text:'Révisions'),Tab(text:'Sources'),Tab(text:'Relecture'),Tab(text:'Publications'),Tab(text:'Historique')]),Expanded(child:TabBarView(children:[_Overview(data:data),_Revisions(data:data,canRestore:canEdit,onRestore:(r)=>_restore(item,r)),_Sources(data:data,canVerify:canEdit||canReview,onVerify:_verifySource),_ReviewTab(data:data),_Publications(data:data),_Audit(data:data)]))])));});
 Future<void> _do(Future<void> Function() action)async{try{await action();if(mounted){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Action enregistrée.')));_reload();}}on StudioApiException catch(e){if(!mounted)return;final msg=e.isConflict?'Ce contenu a été modifié par quelqu’un d’autre. La fiche va être rechargée.':_errorLabel(e.code);ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(msg)));_reload();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Action impossible : $e')));}}
 String _errorLabel(String code)=>switch(code){'review_checklist_incomplete'=>'La checklist qualité doit être entièrement validée.','high_risk_separation_of_duties_required'=>'Pour un contenu médical, auteur, relecteur et publicateur doivent être distincts.','source_verification_requires_second_person'=>'Une deuxième personne doit vérifier cette source OCR.','distribution_rights_not_cleared'=>'Les droits de diffusion ne sont pas encore validés.','ocr_source_requires_human_verification'=>'Une source OCR doit encore être vérifiée.','review_assigned_to_another_member'=>'Cette relecture est affectée à un autre membre.','publication_assigned_to_another_member'=>'Cette publication est affectée à un autre membre.',_=>code.replaceAll('_',' ')};
 Future<void> _submit(Map<String,dynamic> item)=>_do(()async{await widget.api.submitReview(widget.itemId,item['row_version'] as int);});
 Future<void> _archive(Map<String,dynamic> item)async{final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Archiver ce contenu ?'),content:const Text('Le cours disparaîtra du catalogue actif, mais l’historique et les versions resteront conservés.'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Annuler')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Archiver'))]));if(ok==true)await _do(()async{await widget.api.archive(widget.itemId,item['row_version'] as int);});}
 Future<void> _publish(Map<String,dynamic> item)async{final c=TextEditingController();final text=await showDialog<String>(context:context,builder:(ctx)=>AlertDialog(title:const Text('Publier cette révision'),content:SizedBox(width:520,child:TextField(controller:c,autofocus:true,maxLines:4,decoration:const InputDecoration(labelText:'Changelog *',hintText:'Décris ce qui change pour les étudiants.'))),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Annuler')),FilledButton.icon(onPressed:()=>Navigator.pop(ctx,c.text.trim()),icon:const Icon(Icons.publish),label:const Text('Publier'))]));if(text!=null&&text.isNotEmpty)await _do(()async{await widget.api.publish(widget.itemId,text,item['row_version'] as int);});}
 Future<void> _review(Map<String,dynamic> item)async{final result=await showDialog<Map<String,dynamic>>(context:context,builder:(_)=>_ReviewDialog(highRisk:['medical','high_stakes'].contains(item['risk'])));if(result!=null)await _do(()async{await widget.api.review(widget.itemId,{...result,'expected_version':item['row_version']});});}
 Future<void> _verifySource(Map<String,dynamic> source)=>_do(()async{await widget.api.verifySource(source['id'] as String);});
 Future<void> _restore(Map<String,dynamic> item,Map<String,dynamic> revision)async{final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:Text('Restaurer R${revision['revision_no']} ?'),content:const Text('EduNova créera une nouvelle révision brouillon. L’historique existant ne sera jamais écrasé.'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Annuler')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Créer le brouillon'))]));if(ok==true)await _do(()async{await widget.api.restoreRevision(widget.itemId,revision['id'] as String,{'note':'Restauration de R${revision['revision_no']}','expected_version':item['row_version']});});}
 Future<void> _assign(Map<String,dynamic> item)async{List<dynamic> members;try{members=await widget.api.members();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Impossible de charger l’équipe : $e')));return;}if(!mounted)return;final r=await showDialog<Map<String,dynamic>>(context:context,builder:(_)=>_AssignDialog(members:members));if(r!=null)await _do(()async{await widget.api.assign(widget.itemId,r['assignee_id'],r['stage'],r['due_at']);});}
 Future<void> _editMetadata(Map<String,dynamic> item)async{final r=await showDialog<Map<String,dynamic>>(context:context,builder:(_)=>_MetadataDialog(item:item));if(r!=null)await _do(()async{await widget.api.updateItem(widget.itemId,{...r,'expected_version':item['row_version']});});}
 Future<void> _addRevision(Map<String,dynamic> data)async{final item=data['item'] as Map<String,dynamic>;final revisions=(data['revisions'] as List<dynamic>);Map<String,dynamic>? previous;if(revisions.isNotEmpty)previous=(revisions.last as Map<String,dynamic>)['payload'] as Map<String,dynamic>?;final r=await showDialog<Map<String,dynamic>>(context:context,builder:(_)=>_RevisionDialog(previous:previous));if(r!=null)await _do(()async{await widget.api.addRevision(widget.itemId,{...r,'expected_version':item['row_version']});});}
}

class _Header extends StatelessWidget{final Map<String,dynamic> item;final String role;final VoidCallback? onEdit;const _Header({required this.item,required this.role,this.onEdit});@override Widget build(BuildContext c)=>Container(width:double.infinity,padding:const EdgeInsets.fromLTRB(24,20,24,18),color:Theme.of(c).colorScheme.surfaceContainerLow,child:Wrap(alignment:WrapAlignment.spaceBetween,crossAxisAlignment:WrapCrossAlignment.center,runSpacing:12,children:[ConstrainedBox(constraints:const BoxConstraints(maxWidth:850),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Wrap(spacing:8,runSpacing:8,children:[StatusPill(prettyState(item['state']),color:stateColor(c,item['state'])),StatusPill(prettyKind(item['kind'])),StatusPill(prettyRisk(item['risk']),color:['medical','high_stakes'].contains(item['risk'])?Colors.deepOrange:null),StatusPill(prettyRights(item['rights_status']),color:['authorized','public_domain'].contains(item['rights_status'])?Colors.green:Colors.orange)]),const SizedBox(height:12),Text(item['title']??'',style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:4),Text('${item['faculty_domain']} • ${item['program']} • ${item['level']}${item['semester']!=null?' • ${item['semester']}':''}'),const SizedBox(height:5),Text('Version de ligne ${item['row_version']} • mis à jour ${formatDate(item['updated_at'])}',style:Theme.of(c).textTheme.bodySmall)])),Column(crossAxisAlignment:CrossAxisAlignment.end,children:[StatusPill('Rôle : $role',icon:Icons.shield_outlined),if(onEdit!=null)...[const SizedBox(height:8),OutlinedButton.icon(onPressed:onEdit,icon:const Icon(Icons.edit_outlined),label:const Text('Métadonnées'))]])]));}
class _ActionBar extends StatelessWidget{final Map<String,dynamic> item;final VoidCallback? onRevision,onSubmit,onReview,onPublish,onArchive,onAssign;const _ActionBar({required this.item,this.onRevision,this.onSubmit,this.onReview,this.onPublish,this.onArchive,this.onAssign});@override Widget build(BuildContext c){final actions=<Widget>[if(onRevision!=null)OutlinedButton.icon(onPressed:onRevision,icon:const Icon(Icons.add_box_outlined),label:const Text('Nouvelle révision')),if(onSubmit!=null)FilledButton.tonalIcon(onPressed:onSubmit,icon:const Icon(Icons.rate_review_outlined),label:const Text('Envoyer en relecture')),if(onReview!=null)FilledButton.icon(onPressed:onReview,icon:const Icon(Icons.fact_check),label:const Text('Relire')),if(onPublish!=null)FilledButton.icon(onPressed:onPublish,icon:const Icon(Icons.publish),label:const Text('Publier')),if(onArchive!=null)OutlinedButton.icon(onPressed:onArchive,icon:const Icon(Icons.archive_outlined),label:const Text('Archiver')),if(onAssign!=null)TextButton.icon(onPressed:onAssign,icon:const Icon(Icons.assignment_ind_outlined),label:const Text('Affecter'))];return Container(width:double.infinity,padding:const EdgeInsets.fromLTRB(24,12,24,12),child:Wrap(spacing:10,runSpacing:10,children:actions));}}

class _Overview extends StatelessWidget{final Map<String,dynamic> data;const _Overview({required this.data});@override Widget build(BuildContext c){final item=data['item'] as Map<String,dynamic>;final rg=data['review_gates'] as List<dynamic>;final pg=data['publish_gates'] as List<dynamic>;return ListView(padding:const EdgeInsets.all(24),children:[LayoutBuilder(builder:(c,box){final wide=box.maxWidth>850;final info=StudioSection(title:'Informations',child:Column(children:[_K('Droits',prettyRights(item['rights_status'])),_K('Risque',prettyRisk(item['risk'])),_K('Créé par',item['created_by']??'—'),_K('Empreinte source',(item['source_fingerprint']??'').toString().isEmpty?'Non définie':item['source_fingerprint'])]));final gate=StudioSection(title:'Contrôles qualité',subtitle:'Ces contrôles sont calculés automatiquement à partir de la provenance et du workflow.',child:Column(children:[for(final g in rg)GateTile(gate:g as Map<String,dynamic>)]));return wide?Row(crossAxisAlignment:CrossAxisAlignment.start,children:[Expanded(child:info),const SizedBox(width:14),Expanded(child:gate)]):Column(children:[info,const SizedBox(height:14),gate]);}),const SizedBox(height:14),StudioSection(title:'Prépublication',subtitle:'État des conditions nécessaires avant publication.',child:Column(children:[for(final g in pg)GateTile(gate:g as Map<String,dynamic>)]))]);}}
class _K extends StatelessWidget{final String k;final dynamic v;const _K(this.k,this.v);@override Widget build(BuildContext c)=>Padding(padding:const EdgeInsets.symmetric(vertical:7),child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[SizedBox(width:150,child:Text(k,style:Theme.of(c).textTheme.bodyMedium?.copyWith(color:Theme.of(c).colorScheme.onSurfaceVariant))),Expanded(child:Text('$v',style:Theme.of(c).textTheme.bodyMedium?.copyWith(fontWeight:FontWeight.w700)))]));}

class _Revisions extends StatelessWidget{final Map<String,dynamic> data;final bool canRestore;final ValueChanged<Map<String,dynamic>> onRestore;const _Revisions({required this.data,required this.canRestore,required this.onRestore});@override Widget build(BuildContext c){final rows=(data['revisions'] as List<dynamic>);if(rows.isEmpty)return const StudioEmptyState(icon:Icons.history_edu_outlined,title:'Aucune révision',message:'Ajoute une première révision avant la relecture.');return ListView.separated(padding:const EdgeInsets.all(24),itemCount:rows.length,separatorBuilder:(_,__)=>const SizedBox(height:10),itemBuilder:(c,i){final r=rows[rows.length-1-i] as Map<String,dynamic>;return Card(child:ExpansionTile(leading:CircleAvatar(child:Text('R${r['revision_no']}')),title:Text(r['note']?.toString().isEmpty==false?r['note']:'Révision ${r['revision_no']}',style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text('${r['ai_generated']==true?'IA assistée':'Humaine'} • ${formatDate(r['created_at'])}'),trailing:canRestore?IconButton(tooltip:'Restaurer comme nouveau brouillon',onPressed:()=>onRestore(r),icon:const Icon(Icons.restore)):null,children:[Padding(padding:const EdgeInsets.fromLTRB(18,0,18,18),child:SelectableText(const JsonEncoder.withIndent('  ').convert(r['payload']??{}),style:Theme.of(c).textTheme.bodySmall))]));});}}
class _Sources extends StatelessWidget{final Map<String,dynamic> data;final bool canVerify;final ValueChanged<Map<String,dynamic>> onVerify;const _Sources({required this.data,required this.canVerify,required this.onVerify});@override Widget build(BuildContext c){final rows=data['sources'] as List<dynamic>;if(rows.isEmpty)return const StudioEmptyState(icon:Icons.document_scanner_outlined,title:'Aucune source attachée',message:'Les sources arriveront depuis le pipeline d’ingestion. Les contenus à risque élevé doivent conserver une provenance traçable.');return ListView.separated(padding:const EdgeInsets.all(24),itemCount:rows.length,separatorBuilder:(_,__)=>const SizedBox(height:10),itemBuilder:(c,i){final s=rows[i] as Map<String,dynamic>;final verified=s['human_verified']==true;final confidence=s['ocr_confidence'];return Card(child:ListTile(contentPadding:const EdgeInsets.all(16),leading:Icon(verified?Icons.verified_rounded:Icons.document_scanner_outlined,color:verified?Colors.green:Colors.orange),title:Text(s['filename']??'',style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text('SHA-256 ${s['checksum_sha256']}\n${confidence==null?'Document natif':'OCR ${(confidence*100).toStringAsFixed(0)} %'} • importé ${formatDate(s['created_at'])}'),isThreeLine:true,trailing:verified?const StatusPill('Vérifiée',color:Colors.green):canVerify?FilledButton.tonal(onPressed:()=>onVerify(s),child:const Text('Vérifier')):const StatusPill('À vérifier',color:Colors.orange)));});}}
class _ReviewTab extends StatelessWidget {
  final Map<String, dynamic> data;
  const _ReviewTab({required this.data});
  @override
  Widget build(BuildContext context) {
    final reviews = data['reviews'] as List<dynamic>;
    final assignments = data['assignments'] as List<dynamic>;
    return ListView(padding: const EdgeInsets.all(24), children: [
      StudioSection(title: 'Affectations', child: assignments.isEmpty
        ? const Text('Aucune affectation explicite.')
        : Column(children: [
          for (final assignment in assignments.where((row) => (row as Map)['active'] == true))
            ListTile(contentPadding: EdgeInsets.zero,
              leading: const Icon(Icons.assignment_ind_outlined),
              title: Text("${assignment['stage']} • ${assignment['assignee_id']}"),
              subtitle: Text(assignment['due_at'] == null
                ? 'Sans échéance' : "Échéance ${formatDate(assignment['due_at'])}")),
        ])),
      const SizedBox(height: 14),
      StudioSection(title: 'Décisions de revue', child: reviews.isEmpty
        ? const Text('Aucune décision enregistrée.')
        : Column(children: [
          for (final review in reviews.reversed)
            ListTile(contentPadding: EdgeInsets.zero,
              leading: Icon(review['decision'] == 'approved' ? Icons.check_circle : Icons.change_circle,
                color: review['decision'] == 'approved' ? Colors.green : Colors.orange),
              title: Text("${review['decision'] == 'approved' ? 'Approuvé' : 'Corrections demandées'} • ${review['reviewer_id']}"),
              subtitle: Text("${review['comment']?.toString().isNotEmpty == true ? review['comment'] : 'Sans commentaire'}\n${formatDate(review['created_at'])}${review['quality_score'] != null ? ' • qualité ${review['quality_score']} %' : ''}"),
              isThreeLine: true),
        ])),
    ]);
  }
}
