class _ReviewDialogState extends State<_ReviewDialog>{final comment=TextEditingController();bool approve=true;final checks=<String,bool>{};List<(String,String)> get defs=>widget.highRisk?const[('factual_accuracy','Exactitude factuelle'),('source_traceability','Traçabilité des sources'),('scope_alignment','Conforme au périmètre du cours'),('language_quality','Qualité de langue'),('safety','Sécurité / absence de conseil dangereux')]:const[('source_traceability','Traçabilité des sources'),('structure_quality','Structure et lisibilité'),('rights_checked','Droits vérifiés')];@override Widget build(BuildContext c)=>AlertDialog(title:const Text('Relecture qualité'),content:SizedBox(width:580,child:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.stretch,children:[SegmentedButton<bool>(segments:const[ButtonSegment(value:true,label:Text('Approuver'),icon:Icon(Icons.check)),ButtonSegment(value:false,label:Text('Demander des corrections'),icon:Icon(Icons.edit_note))],selected:{approve},onSelectionChanged:(v)=>setState(()=>approve=v.first)),const SizedBox(height:16),if(approve)...[Text('Checklist obligatoire',style:Theme.of(c).textTheme.titleMedium?.copyWith(fontWeight:FontWeight.w700)),const SizedBox(height:6),for(final d in defs)CheckboxListTile(contentPadding:EdgeInsets.zero,title:Text(d.$2),value:checks[d.$1]??false,onChanged:(v)=>setState(()=>checks[d.$1]=v??false))],const SizedBox(height:8),TextField(controller:comment,maxLines:4,decoration:InputDecoration(labelText:approve?'Commentaire (optionnel)':'Corrections à apporter *'))]))),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Annuler')),FilledButton(onPressed:()=>Navigator.pop(c,{'approve':approve,'comment':comment.text.trim(),'checklist':checks}),child:Text(approve?'Approuver':'Renvoyer'))]);}

