class _MetadataDialogState extends State<_MetadataDialog>{late final TextEditingController title,domain,program,level,semester,note;late String risk,rights;@override void initState(){super.initState();title=TextEditingController(text:widget.item['title']);domain=TextEditingController(text:widget.item['faculty_domain']);program=TextEditingController(text:widget.item['program']);level=TextEditingController(text:widget.item['level']);semester=TextEditingController(text:widget.item['semester']??'');note=TextEditingController(text:widget.item['rights_note']??'');risk=widget.item['risk'];rights=widget.item['rights_status'];}@override Widget build(BuildContext c)=>AlertDialog(title:const Text('Métadonnées'),content:SizedBox(width:600,child:SingleChildScrollView(child:Column(children:[TextField(controller:title,decoration:const InputDecoration(labelText:'Titre')),const SizedBox(height:10),TextField(controller:domain,decoration:const InputDecoration(labelText:'Domaine')),const SizedBox(height:10),TextField(controller:program,decoration:const InputDecoration(labelText:'Programme')),const SizedBox(height:10),Row(children:[Expanded(child:TextField(controller:level,decoration:const InputDecoration(labelText:'Niveau'))),const SizedBox(width:10),Expanded(child:TextField(controller:semester,decoration:const InputDecoration(labelText:'Semestre')))]),const SizedBox(height:10),Row(children:[Expanded(child:DropdownButtonFormField(value:risk,decoration:const InputDecoration(labelText:'Risque'),items:const[DropdownMenuItem(value:'standard',child:Text('Standard')),DropdownMenuItem(value:'medical',child:Text('Médical')),DropdownMenuItem(value:'high_stakes',child:Text('Enjeu élevé'))],onChanged:(v)=>setState(()=>risk=v!))),const SizedBox(width:10),Expanded(child:DropdownButtonFormField(value:rights,decoration:const InputDecoration(labelText:'Droits'),items:const[DropdownMenuItem(value:'unknown',child:Text('À vérifier')),DropdownMenuItem(value:'authorized',child:Text('Autorisé')),DropdownMenuItem(value:'public_domain',child:Text('Domaine public')),DropdownMenuItem(value:'internal_only',child:Text('Interne')),DropdownMenuItem(value:'restricted',child:Text('Restreint'))],onChanged:(v)=>setState(()=>rights=v!)))]),const SizedBox(height:10),TextField(controller:note,maxLines:3,decoration:const InputDecoration(labelText:'Note sur les droits'))]))),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Annuler')),FilledButton(onPressed:()=>Navigator.pop(c,{'title':title.text.trim(),'faculty_domain':domain.text.trim(),'program':program.text.trim(),'level':level.text.trim(),'semester':semester.text.trim().isEmpty?null:semester.text.trim(),'risk':risk,'rights_status':rights,'rights_note':note.text.trim()}),child:const Text('Enregistrer'))]);}

class _RevisionDialog extends StatefulWidget{final Map<String,dynamic>? previous;const _RevisionDialog({this.previous});@override State<_RevisionDialog> createState()=>_RevisionDialogState();}
class _RevisionDialogState extends State<_RevisionDialog>{late final TextEditingController description,label,year,note,source,prompt,advanced;bool premium=true,ai=false;@override void initState(){super.initState();final p=widget.previous??{};description=TextEditingController(text:p['description']?.toString()??'');label=TextEditingController(text:p['version_label']?.toString()??'');year=TextEditingController(text:p['academic_year']?.toString()??'');premium=p['premium_required']!=false;note=TextEditingController();source=TextEditingController();prompt=TextEditingController();advanced=TextEditingController(text:'{}');}@override Widget build(BuildContext c)=>AlertDialog(title:const Text('Nouvelle révision'),content:SizedBox(width:680,child:SingleChildScrollView(child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[TextField(controller:description,maxLines:3,decoration:const InputDecoration(labelText:'Description')),const SizedBox(height:10),Row(children:[Expanded(child:TextField(controller:label,decoration:const InputDecoration(labelText:'Version / libellé'))),const SizedBox(width:10),Expanded(child:TextField(controller:year,decoration:const InputDecoration(labelText:'Année académique')))]),SwitchListTile(contentPadding:EdgeInsets.zero,title:const Text('Contenu Premium'),value:premium,onChanged:(v)=>setState(()=>premium=v)),TextField(controller:source,decoration:const InputDecoration(labelText:'Empreinte / référence source')),const SizedBox(height:10),SwitchListTile(contentPadding:EdgeInsets.zero,title:const Text('Révision assistée par IA'),value:ai,onChanged:(v)=>setState(()=>ai=v)),if(ai)TextField(controller:prompt,decoration:const InputDecoration(labelText:'Version du prompt *')),const SizedBox(height:10),TextField(controller:note,maxLines:2,decoration:const InputDecoration(labelText:'Note de révision')),const SizedBox(height:12),ExpansionTile(tilePadding:EdgeInsets.zero,title:const Text('Payload avancé (JSON)'),subtitle:const Text('Pour les champs spécialisés en attendant le pipeline d’ingestion LOT 12.'),children:[TextField(controller:advanced,minLines:4,maxLines:10,style:const TextStyle(fontFamily:'monospace'),decoration:const InputDecoration(hintText:'{}'))])]))),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Annuler')),FilledButton(onPressed:(){Map<String,dynamic> extra={};try{final v=jsonDecode(advanced.text.trim().isEmpty?'{}':advanced.text);if(v is Map<String,dynamic>)extra=v;else throw const FormatException();}catch(_){ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('JSON avancé invalide.')));return;}Navigator.pop(c,{'payload':{...extra,'description':description.text.trim(),'version_label':label.text.trim(),'academic_year':year.text.trim().isEmpty?null:year.text.trim(),'premium_required':premium},'source_fingerprint':source.text.trim(),'ai_generated':ai,'prompt_version':ai?prompt.text.trim():null,'note':note.text.trim()});},child:const Text('Créer la révision'))]);}
